  const { ProfileService } = require('../.build/service');
  const snap = (s) => JSON.stringify(s.profile);
  const fresh = () => new ProfileService({ displayName: 'before', tags: ['old'] });

  // empty object is a no-op
  let s = fresh();
  assert.deepEqual(s.patch({}), { displayName: 'before', tags: ['old'] });

  // null clears displayName; [] and null clear tags
  s = fresh();
  assert.deepEqual(s.patch({ displayName: null, tags: [] }), { displayName: null, tags: [] });
  s = fresh();
  assert.deepEqual(s.patch({ tags: null }), { displayName: 'before', tags: [] });

  // trimming and tag dedupe after trim
  s = fresh();
  assert.deepEqual(s.patch({ displayName: '  Ann  ', tags: [' a ', 'b'] }), { displayName: 'Ann', tags: ['a', 'b'] });

  // caller's array is not reused for storage
  const mine = ['x'];
  s = fresh();
  s.patch({ tags: mine });
  assert.notEqual(s.profile.tags, mine);
  mine.push('y');
  assert.deepEqual(s.profile.tags, ['x']);

  // invalid inputs throw and leave storage unchanged
  const bad = [
    null, 1, 'str', [], ['a'], Object.create({ displayName: 'x' }),
    { displayName: 5 }, { displayName: '   ' }, { displayName: 'a'.repeat(41) },
    { displayName: undefined }, { tags: 'a' }, { tags: [1] }, { tags: [''] },
    { tags: [' ', 'a'] }, { tags: ['a', ' a '] }, { tags: ['a', 'b', 'c', 'd', 'e', 'f'] },
    { tags: ['a'.repeat(13)] }, { tags: [undefined] }, { tags: {} }, { extra: 1 },
    { displayName: 'ok', tags: [1] }, { tags: [ 'a', , 'b'] },
  ];
  for (const input of bad) {
    s = fresh();
    const before = snap(s);
    assert.throws(() => s.patch(input), /invalid profile/);
    assert.equal(snap(s), before);
  }

  // boundary values accepted
  s = fresh();
  assert.deepEqual(s.patch({ displayName: 'a'.repeat(40), tags: ['t'.repeat(12), 'a', 'b', 'c', 'd'] }).tags.length, 5);

  // accessor-based key rejected
  s = fresh();
  assert.throws(() => s.patch(Object.defineProperty({}, 'tags', { get: () => [], enumerable: true })), /invalid profile/);
}
console.log('public checks passed');
